    if n == 0:
        return []
    m = len(processing_times[0])

    # ----- makespan computation -----
    def makespan(seq):
        dp = [0] * m
        for j in seq:
            t0 = processing_times[j][0]
            dp[0] += t0
            for c in range(1, m):
                # dp[c] = max(dp[c-1], dp[c]) + processing_times[j][c]
                if dp[c-1] > dp[c]:
                    dp[c] = dp[c-1] + processing_times[j][c]
                else:
                    dp[c] = dp[c] + processing_times[j][c]
        return dp[-1]

    # ----- NEH construction given an ordering -----
    def neh_construct(order):
        seq = [order[0]]
        for job in order[1:]:
            best_pos = 0
            best_val = float('inf')
            # try inserting job at each position
            for pos in range(len(seq) + 1):
                cand = seq[:pos] + [job] + seq[pos:]
                val = makespan(cand)
                if val < best_val:
                    best_val = val
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

